<script setup>
import{onMounted,reactive,ref}from'vue';import AdminLayout from'../../components/admin/AdminLayout.vue';import{adminJson}from'../../services/adminAuth';const filters=reactive({date_from:'',date_to:''}),data=ref({confirmed_donors:0,confirmed_donations:0,confirmed_amount:0,pending:0,rejected:0,by_purpose:[]});async function load(){const q=new URLSearchParams;Object.entries(filters).forEach(([k,v])=>v&&q.set(k,v));data.value=await adminJson(`/api/admin/reports?${q}`)}onMounted(load)
</script>
<template><AdminLayout><div class="admin-title"><div><p>হিসাব ও বিশ্লেষণ</p><h1>রিপোর্ট</h1></div></div><section class="panel"><form class="report-filters" @submit.prevent="load"><label>শুরুর তারিখ<input v-model="filters.date_from" type="date"></label><label>শেষ তারিখ<input v-model="filters.date_to" type="date"></label><button class="admin-button">রিপোর্ট দেখুন</button></form></section><div class="stat-grid report-stats"><article><p>নিশ্চিত দাতা</p><strong>{{data.confirmed_donors}}</strong></article><article><p>নিশ্চিত দান</p><strong>{{data.confirmed_donations}}</strong></article><article><p>মোট পরিমাণ</p><strong>৳ {{Number(data.confirmed_amount).toLocaleString('bn-BD')}}</strong></article><article><p>অপেক্ষমাণ</p><strong>{{data.pending}}</strong></article><article><p>প্রত্যাখ্যাত</p><strong>{{data.rejected}}</strong></article></div><section class="panel"><div class="panel-head"><div><h2>উদ্দেশ্যভিত্তিক হিসাব</h2><p>শুধুমাত্র নিশ্চিত দান</p></div></div><div class="table-wrap"><table><thead><tr><th>দানের উদ্দেশ্য</th><th>দানের সংখ্যা</th><th>মোট পরিমাণ</th></tr></thead><tbody><tr v-if="!data.by_purpose.length"><td colspan="3"><div class="empty compact">এই সময়ে কোনো নিশ্চিত দান নেই।</div></td></tr><tr v-for="item in data.by_purpose" :key="item.name_bn"><td><b>{{item.name_bn}}</b></td><td>{{item.donations_count}}</td><td>৳ {{Number(item.total_amount).toLocaleString('bn-BD')}}</td></tr></tbody></table></div></section></AdminLayout></template>
